\section{Detailed Proofs}
\paragraph{Relationship between $\beta$/$\gamma$ and $\beta_{new}$/$\gamma_{new}$.}After the magnitude of $\phi(Q_i)$ is scaled by a factor of $a > 1$, we have:
\begin{equation}
\begin{aligned}
    &\gamma_{new}=\frac{a\phi(Q_i)\sum_{m=1}^N\phi(K_m)^T}{N}=a\gamma,\\
    &\beta_{new}-1=\frac{1}{a\phi(Q_i)\sum_{m=1}^N\phi(K_m)^T}=\frac{1}{a}(\beta-1);
\end{aligned}
\end{equation}
Based on the above two equations, we derive the following result:  
\begin{equation}
    \begin{aligned}
        &\gamma_{new}=a\gamma,\\
        &\beta_{new}=\frac{\beta+a-1}{a};
    \end{aligned}
\end{equation}

\paragraph{Proof of $\frac{a\beta}{a+\beta-1}>1$.}Since $\beta>1$ and $a>1$, we have:
\begin{equation}
    (a-1)(\beta-1)>0,
\end{equation}
Expanding the equation, we obtain:  
\begin{equation}
\label{eq:1}
\begin{aligned}
& a\beta-(a+\beta-1)>0, \\
& a\beta>a+\beta-1;
\end{aligned}
\end{equation}
Since $a+\beta>1+1=2>1$, so $a+\beta-1>0$. Based on Eq.~\ref{eq:1}, we have:
\begin{equation}
    \frac{a\beta}{a+\beta-1}>1
\end{equation}

\paragraph{Proof of $p_m>p$.}We define:
\begin{equation}
\begin{aligned}
&A_m=\beta \phi(Q_i)\phi(K_m)^T,\\
&A_n=\beta \phi(Q_i)\phi(K_n)^T;\\
\end{aligned}
\end{equation}
Where we assume that $Q_i$ allocate more attention to $K_m$, thus $A_m>A_n$. Consider a function of \( x \):  
\begin{equation}
    f(x)=\frac{A_m-\gamma x}{A_n-\gamma x};
\end{equation}
The derivative of the function \( f(x) \) can be expressed as:  
\begin{equation}
f'(x) = \frac{\gamma (A_m - A_n)}{(A_n - \gamma x)^2}>0;
\end{equation}

Since we only consider the positive attention scores, we have $\frac{A_n}{\gamma}>\frac{a\beta}{a+\beta-1}>1$, the function \( f(x) \) is monotonically increasing. Thus $p_m=f(\frac{a\beta}{a+\beta-1})>f(1)=p$.

